-- 0511_ride_places_catalog | Ride places come only from official catalogs
-- (docs/spec/05_giving_worlds.md §5.3 step 2, D71; approved fill S47; gap G45).
--
--   1. public.road_junctions — Ministry of Transport junctions & interchanges (seeded by
--      0512, generated by scripts/import-road-junctions.mjs). Public read, service writes.
--   2. ride_place_lookup(kind, id) — the one resolver of a place to its official label and
--      coordinates: a city (public.cities), a street (public.streets; it has no coordinates,
--      so it is pinned at its city) or a junction / interchange.
--   3. list_ride_places() — every pickable city and junction, for the place picker.
--   4. Ride details gain origin/dest place kind + id and up to 3 meeting points.
--   5. listings_ride_places_canonical — on every native ride write, each place must resolve,
--      and its label, coordinates and city are overwritten from the catalog, so a client can
--      never publish a free-text place or move a pin (D71). At most 3 meeting points.

begin;

-- ── 1. Junctions & interchanges catalog ──────────────────────────────────────
create table if not exists public.road_junctions (
  junction_id integer primary key,                 -- the source's NUM, stable across refreshes
  kind        text not null check (kind in ('junction', 'interchange')),
  name_he     text not null,
  name_en     text,
  name_ar     text,
  roads       text,                                -- e.g. "2/5": the roads that meet there
  lat         double precision not null check (lat between -90 and 90),
  lng         double precision not null check (lng between -180 and 180)
);

create index if not exists road_junctions_name_he_idx on public.road_junctions (name_he);

alter table public.road_junctions enable row level security;

drop policy if exists road_junctions_public_read on public.road_junctions;
create policy road_junctions_public_read
  on public.road_junctions for select
  to anon, authenticated
  using (true);

comment on table public.road_junctions is
  'Ministry of Transport junction & interchange names (data.gov.il zmt_names, CC BY), existing places only. Seeded by migration from scripts/import-road-junctions.mjs; never fetched at runtime (D71, S47).';

-- ── 2. One resolver for every ride place ─────────────────────────────────────
-- Place ids: city → city_id; street → '<city_id>:<street_id>'; junction → junction_id.
create or replace function public.ride_place_lookup(p_kind text, p_id text)
returns table (label text, lat double precision, lng double precision, city_id text)
language sql
stable
set search_path = public
as $$
  select c.name_he, c.lat, c.lon, c.city_id
    from public.cities c
   where p_kind = 'city' and c.city_id = p_id and c.lat is not null and c.lon is not null
  union all
  select s.name_he || ', ' || c.name_he, c.lat, c.lon, c.city_id
    from public.streets s
    join public.cities c on c.city_id = s.city_id
   where p_kind = 'street'
     and s.city_id = split_part(p_id, ':', 1)
     and split_part(p_id, ':', 2) ~ '^[0-9]+$'
     and s.street_id = split_part(p_id, ':', 2)::int
     and c.lat is not null and c.lon is not null
  union all
  select (case j.kind when 'interchange' then 'מחלף ' else 'צומת ' end) || j.name_he, j.lat, j.lng, null
    from public.road_junctions j
   where p_kind = 'junction' and p_id ~ '^[0-9]+$' and j.junction_id = p_id::int
  limit 1;
$$;

comment on function public.ride_place_lookup(text, text) is
  'Official label + coordinates of a ride place (city / street / junction), or no row (D71).';

-- ── 3. Every pickable place, for the picker ──────────────────────────────────
-- Cities with coordinates and all junctions (~1,800 rows) in one uniform shape; the app
-- loads it once and filters on the device, like the city picker. Streets are picked
-- inside a chosen city (public.streets), so they are not listed here.
create or replace function public.list_ride_places()
returns table (
  place_kind text,
  place_id   text,
  label      text,
  city_id    text,
  lat        double precision,
  lng        double precision
)
language sql
stable
set search_path = public
as $$
  select 'city'::text, c.city_id, c.name_he, c.city_id, c.lat, c.lon
    from public.cities c
   where c.lat is not null and c.lon is not null
  union all
  select 'junction', j.junction_id::text,
         (case j.kind when 'interchange' then 'מחלף ' else 'צומת ' end) || j.name_he,
         null, j.lat, j.lng
    from public.road_junctions j
  order by 3;
$$;

comment on function public.list_ride_places() is
  'Cities and junctions/interchanges a ride place can be picked from (D71).';

-- ── 4. Ride details: place identity and meeting points ───────────────────────
-- Added to both ride kinds without rewriting the rest of their schema.
update public.listing_kinds
   set detail_schema = jsonb_set(
         detail_schema, '{properties}',
         (detail_schema->'properties') || '{
           "origin_place_kind":{"enum":["city","street","junction"]},
           "origin_place_id":{"type":"string","maxLength":64},
           "dest_place_kind":{"enum":["city","street","junction"]},
           "dest_place_id":{"type":"string","maxLength":64},
           "meeting_points":{
             "type":"array",
             "maxItems":3,
             "items":{
               "type":"object",
               "additionalProperties":false,
               "required":["kind","id"],
               "properties":{
                 "kind":{"enum":["city","street","junction"]},
                 "id":{"type":"string","maxLength":64},
                 "label":{"type":"string","maxLength":120},
                 "lat":{"type":"number","minimum":-90,"maximum":90},
                 "lng":{"type":"number","minimum":-180,"maximum":180},
                 "city_id":{"type":["string","null"]}
               }
             }
           }
         }'::jsonb)
 where world_slug = 'rides' and slug in ('ride_offer', 'ride_request');

-- ── 5. Every place of a native ride is official and canonical ────────────────
-- Writes one resolved route end (origin / dest) into the details, or raises.
create or replace function public.ride_details_with_place(p_details jsonb, p_end text)
returns jsonb
language plpgsql
stable
set search_path = public
as $$
declare
  v_kind text := p_details->>(p_end || '_place_kind');
  v_id text := p_details->>(p_end || '_place_id');
  v_place record;
  v_out jsonb;
begin
  if v_kind is null then
    -- Builds before 0511 send only the city; a city id is still an official place.
    if p_details ? (p_end || '_city_id') then
      v_kind := 'city';
      v_id := p_details->>(p_end || '_city_id');
    elsif p_details ? (p_end || '_lat') or p_details ? (p_end || '_label') then
      raise exception 'ride_place_invalid' using errcode = '23514';
    else
      return p_details; -- this end was not given (the form requires both before publishing)
    end if;
  end if;

  select * into v_place from public.ride_place_lookup(v_kind, v_id);
  if not found then raise exception 'ride_place_invalid' using errcode = '23514'; end if;

  v_out := (p_details - (p_end || '_city_id')) || jsonb_build_object(
    p_end || '_place_kind', v_kind,
    p_end || '_place_id', v_id,
    p_end || '_label', v_place.label,
    p_end || '_lat', v_place.lat,
    p_end || '_lng', v_place.lng);
  -- A junction belongs to no city, so its end carries no city id.
  if v_place.city_id is not null then
    v_out := v_out || jsonb_build_object(p_end || '_city_id', v_place.city_id);
  end if;
  return v_out;
end;
$$;

create or replace function public.listings_ride_places_canonical()
returns trigger
language plpgsql
set search_path = public
as $$
declare
  v_point jsonb;
  v_place record;
  v_points jsonb := '[]'::jsonb;
begin
  if new.world_slug <> 'rides' or new.origin <> 'native' then return new; end if;

  new.details := public.ride_details_with_place(coalesce(new.details, '{}'::jsonb), 'origin');
  new.details := public.ride_details_with_place(new.details, 'dest');

  if jsonb_typeof(new.details->'meeting_points') = 'array' then
    -- Enforced here too: the details schema check alone is not relied on (see TECH_DEBT).
    if jsonb_array_length(new.details->'meeting_points') > 3 then
      raise exception 'too_many_meeting_points' using errcode = '23514';
    end if;
    for v_point in select * from jsonb_array_elements(new.details->'meeting_points') loop
      select * into v_place from public.ride_place_lookup(v_point->>'kind', v_point->>'id');
      if not found then raise exception 'ride_place_invalid' using errcode = '23514'; end if;
      v_points := v_points || jsonb_build_array(jsonb_build_object(
        'kind', v_point->>'kind', 'id', v_point->>'id', 'label', v_place.label,
        'lat', v_place.lat, 'lng', v_place.lng, 'city_id', v_place.city_id));
    end loop;
    new.details := jsonb_set(new.details, '{meeting_points}', v_points);
  end if;

  return new;
end;
$$;

-- BEFORE triggers fire in name order; this one runs before listings_validate_details_trg,
-- so the schema check sees the canonical details.
drop trigger if exists listings_ride_places_canonical on public.listings;
create trigger listings_ride_places_canonical
  before insert or update of details on public.listings
  for each row execute function public.listings_ride_places_canonical();

-- ── Grants ───────────────────────────────────────────────────────────────────
revoke all on function public.ride_place_lookup(text, text) from public;
revoke all on function public.list_ride_places() from public;
revoke all on function public.ride_details_with_place(jsonb, text) from public, anon;
revoke all on function public.listings_ride_places_canonical() from public, anon, authenticated;
grant execute on function public.ride_place_lookup(text, text) to anon, authenticated;
grant execute on function public.list_ride_places() to anon, authenticated;
-- The canonical-places trigger runs as the writer, who must be able to call its helper.
grant execute on function public.ride_details_with_place(jsonb, text) to authenticated, service_role;

commit;
